using Kaluz.Web.Services;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Authorization;
namespace Kaluz.Web.Controllers;
[Authorize]public class HomeController(Db db):Controller{public IActionResult Index(){try{ViewBag.Ventas=db.Scalar("SELECT COALESCE(SUM(Total),0) FROM Venta WHERE Estado='Completada' AND Fecha >= DATEADD(day,-30,SYSDATETIME())");ViewBag.Productos=db.Scalar("SELECT COUNT(*) FROM Producto WHERE Activo=1");ViewBag.Bajos=db.Scalar("SELECT COUNT(*) FROM vw_StockBajo");ViewBag.Clientes=db.Scalar("SELECT COUNT(*) FROM Cliente WHERE Activo=1");ViewBag.Recientes=db.List("SELECT TOP 7 NumeroTicket,Fecha,Total,Estado FROM Venta ORDER BY IdVenta DESC");}catch(Exception ex){ViewBag.Error="No se pudo consultar la base de datos: "+ex.Message;ViewBag.Recientes=new List<Dictionary<string,object?>>();}return View();} [AllowAnonymous]public IActionResult Error()=>View();}
